const profiles = $('Get every profile').all().map((i) => i.json);
const reports = $input.all().map((i) => i.json);
const num = (n) => (typeof n === 'number' && isFinite(n) ? n.toLocaleString('en-US') : 'n/a');
const signed = (n) => (typeof n === 'number' && isFinite(n) ? (n > 0 ? '+' : '') + n.toLocaleString('en-US') : 'n/a');
const change = (n) => (typeof n === 'number' ? ' (' + (n > 0 ? '+' : '') + n + '% vs the period before)' : '');

const blocks = [];
reports.forEach((r, i) => {
  const name = (profiles[i] && profiles[i].name) || 'Profile ' + (i + 1);
  if (!r || r.error || !r.metrics) {
    blocks.push('*' + name + '*\nNo numbers this time: ' + ((r && r.error) || 'Socialync sent no data.'));
    return;
  }
  const m = r.metrics;
  const ch = r.changes || {};
  const range = r.dateRange ? r.dateRange.start + ' to ' + r.dateRange.end : '';
  const lines = [
    '*' + name + '* ' + range,
    'Views: ' + num(m.views) + change(ch.views),
    'Likes: ' + num(m.likes) + change(ch.likes),
    'Comments: ' + num(m.comments) + change(ch.comments),
    'Shares: ' + num(m.shares) + change(ch.shares),
    'Followers: ' + num(m.followers) + ' (net ' + signed(m.followerChange) + ')',
  ];
  // YouTube reports raw counts only, so it stays out of every ranking and percentage.
  const ranked = Object.entries(r.platforms || {})
    .filter(([platform, p]) => platform !== 'youtube' && p && p.metrics && typeof p.metrics.views === 'number')
    .sort((a, b) => b[1].metrics.views - a[1].metrics.views)
    .slice(0, 3);
  if (ranked.length) lines.push('Most views: ' + ranked.map(([platform, p]) => platform + ' ' + num(p.metrics.views)).join(', '));
  blocks.push(lines.join('\n'));
});
if (!blocks.length) blocks.push('Socialync returned no profiles for this API key.');
const title = $('Settings').first().json.period === 'month' ? 'monthly' : 'weekly';
return [{ json: { digestText: '*Your ' + title + ' Socialync digest*\n\n' + blocks.join('\n\n') } }];
